// src/components/Answers/AnswerForm.js
import React, { useState } from 'react';
import './AnswerForm.css';
import { postAnswer } from '../../services/api';

function AnswerForm({ questionId, onAnswerSubmitted }) {
  const [text, setText] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // Post a new answer via service layer
      const data = await postAnswer(questionId, {
        text,
        question: { id: Number(questionId) },
        user: { id: 1 }
      });
      onAnswerSubmitted(data);
      setText('');
    } catch (error) {
      alert('A apărut o eroare la trimiterea răspunsului.');
      console.error('Eroare postAnswer:', error);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="answer-form">
      <textarea
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Scrie un răspuns..."
      />
      <button type="submit">Trimite răspuns</button>
    </form>
  );
}

export default AnswerForm;
